function A({registerIndicator:h,sourceValues:y,nulls:N}){h({id:"oa-mma",name:"Modified Moving Average (MMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:2,max:4e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"mma",type:"line",title:"MMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,m){const g=Math.max(2,Math.floor(Number(m.period)||10)),t=Math.min(Math.max(2,g),4e3),v=y(l,m.source??"close"),a=new Array(t).fill(NaN),r=new Array(l.length).fill(NaN);let o=0,c=0,e=0;for(let i=0;i<l.length;i++){const n=v[i],s=a[o];if(c=c+(Number.isFinite(n)?n:0)-(Number.isFinite(s)?s:0),e=e+(Number.isFinite(n)?1:0)-(Number.isFinite(s)?1:0),a[o]=n,o=(o+1)%t,e<=0){r[i]=n;continue}const d=c/e;let f=0,p=0;for(let u=0;u<t;u++){const b=a[(o-1-u+t)%t];Number.isFinite(b)&&(f+=(e-(2*p+1))*.5*b,p+=1)}const M=(e+1)*e;r[i]=M===0?d:d+f*6/M}return{mma:N(r)}}})}export{A as default};
